import sys, json, types, os, tempfile
sys.path.insert(0,'.')
import research_sdk

class FakeClient:
    def __init__(self, ctx=None):
        self.completed_items={}
        self.calls=0
    def chat(self, prompt, *, model=None, item_id=None, max_tokens=None, **kw):
        self.calls+=1
        if model=='helper-simulator':
            return {'text':'DIFFERENT','evidence':{'kind':'llm','id':'judge-%d'%self.calls},
                    'operation_id':'op','attempt_count':1,'finish_reason':'end_turn'}
        txt = "ANSWER: 42\n```python\ndef f():\n    return 1\n```"
        return {'text':txt,'evidence':{'kind':'llm','id':'cand-%d'%self.calls},
                'operation_id':'op%d'%self.calls,'attempt_count':1,'finish_reason':'end_turn'}
    def item(self, item_id, prompt, grader, **kw):
        reply=self.chat(prompt,item_id=item_id,**kw)
        g=grader(reply['text']) if reply['text'].strip() else {'score':0,'answer_status':'missing'}
        if not isinstance(g,dict): g={'score':g,'answer_status':'answered'}
        extra=g.get('evidence',[])
        return {**g,'id':item_id,'execution_status':'completed','evidence':[reply['evidence'],*extra],
                'finish_reason':reply['finish_reason'],'operation_id':reply['operation_id'],'attempt_count':1}

research_sdk.Client=FakeClient
out=tempfile.mktemp(suffix='.json')
sys.argv=['run.py','--context','/workspace/access.json','--output',out]
import importlib
run=importlib.import_module('run')
run.Client=FakeClient
run.main()
d=json.load(open(out))
print('rows',len(d['items']),'sandbox',d.get('code_execution_sandbox'))
import collections
print(collections.Counter(r['execution_status'] for r in d['items']))
print('all have question_id',all('question_id' in r for r in d['items']))
print('all have score',all(isinstance(r.get('score'),(int,float)) for r in d['items']))
print('mean',sum(r['score'] for r in d['items'])/len(d['items']))
ids=[r['id'] for r in d['items']]
man=[i['id'] for i in json.load(open('evaluation.json'))['items']]
print('order matches manifest', ids==man)
